import os,re
root='AlgebraicJacobian'
imports={}
for dp,_,fs in os.walk(root):
    for f in fs:
        if f.endswith('.lean'):
            p=os.path.join(dp,f)
            mod=p[:-5].replace('/','.')
            imps=[l.split()[1] for l in open(p) if l.startswith('import ')]
            imports[mod]=imps
def closure(m,seen=None):
    if seen is None: seen=set()
    for i in imports.get(m,[]):
        if i not in seen:
            seen.add(i); closure(i,seen)
    return seen
cl=closure('AlgebraicJacobian.Picard.EffectivityPieces')
print('EffectivityPieces closure size',len(cl))
print('contains DivisorFamily?', [x for x in cl if 'DivisorFamily' in x or 'DivScheme' in x])
EOF
